INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2701, 'Leviticus 3:2', 'Leviticus', 3, 2, '&nbsp;هغه کس به خپل لاس د هغه ځناور په سر کېږدى او د مالِک خُدائ د حضور مقدسې خېمې د دروازې په خولۀ کښې به يې حلال کړى. د هارون د خاندان اِمامان به هغه وينه د قربان‌ګاه څلورو واړو طرفونو ته وشيندى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2702, 'Leviticus 3:3', 'Leviticus', 3, 3, '&nbsp;او هغه دې د هغه ځناور دا حِصې مالِک خُدائ ته په اور سوزېدونکې نذرانې په توګه پېش کړى. په دې کښې به په کولمو باندې ټوله وازګه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2703, 'Leviticus 3:4', 'Leviticus', 3, 4, '&nbsp;پښتورګى او په هغې باندې چې څومره وازګه وى او د اينې ښۀ حِصه هم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2704, 'Leviticus 3:5', 'Leviticus', 3, 5, '&nbsp;اِمامان به دا هر څۀ د سوزېدونکې نذرانو سره په قربان‌ګاه باندې وسوزوى. په اور سوزېدونکې د دې نذرانې خوشبو په مالِک خُدائ باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2705, 'Leviticus 3:6', 'Leviticus', 3, 6, '&nbsp;کۀ چرې د رَمې نه د سلامتۍ د نذرانې په توګه څۀ پېش کولے شى، کۀ هغه نر وى يا ښځه، خو چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2706, 'Leviticus 3:7', 'Leviticus', 3, 7, '&nbsp;کۀ يو کس يو ګډُورے پېش کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2707, 'Leviticus 3:8', 'Leviticus', 3, 8, '&nbsp;نو هغه دې خپل لاس ورله په سر کېږدى او د خېمې مخې ته دې هغه حلال کړى. اِمامان به د هغۀ وينه د قربان‌ګاه په څلورو واړو طرفونو باندې وشيندى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2708, 'Leviticus 3:9', 'Leviticus', 3, 9, '&nbsp;او مالِک خُدائ ته دې د هغه ځناور دا حِصې په اور سوزېدونکې نذرانې په توګه پېش کړى يعنې د ټول لم وازګه چې د ملا د هډُوکى سره نزدې پرې کړے شوې وى، هغه ټوله وازګه چې په کولمو پرته وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2709, 'Leviticus 3:10', 'Leviticus', 3, 10, '&nbsp;پښتورګى او هغه وازګه چې ورباندې پرته وى او د اينې ښۀ حِصه هم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2710, 'Leviticus 3:11', 'Leviticus', 3, 11, '&nbsp;بيا به اِمام دا هر څۀ په اور سوزېدونکې نذرانې په توګه مالِک خُدائ ته وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2711, 'Leviticus 3:12', 'Leviticus', 3, 12, '&nbsp;کۀ يو کس چېلۍ پېش کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2712, 'Leviticus 3:13', 'Leviticus', 3, 13, '&nbsp;هغه دې خپل لاس ورله په سر کېږدى او د خېمې مخې ته دې حلاله کړى. اِمامان به د دې وينه د قربان‌ګاه په څلورو واړو طرفونو باندې وشيندى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2713, 'Leviticus 3:14', 'Leviticus', 3, 14, '&nbsp;او مالِک خُدائ ته دې دا حِصې په اور سوزېدونکې نذرانې په توګه پېش کړى يعنې هغه ټوله وازګه چې په کولمو باندې پرته وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2714, 'Leviticus 3:15', 'Leviticus', 3, 15, '&nbsp;پښتورګى او هغه وازګه چې ورباندې پرته وى او د اينې ښۀ حِصه هم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2715, 'Leviticus 3:16', 'Leviticus', 3, 16, '&nbsp;اِمام به دا هر څۀ په اور سوزېدونکې نذرانې په توګه وسوزوى، دا به په مالِک خُدائ باندې يو ښۀ لګېدونکے بوئ وى. د قربانۍ ټوله وازګه د مالِک خُدائ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2716, 'Leviticus 3:17', 'Leviticus', 3, 17, '&nbsp;يو بنى اِسرائيلے به هم وازګه او وينه نۀ شى خوړلے، بنى اِسرائيل چې چرته هم اوسيږى نو ټول به دا قانون د تل دپاره منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2717, 'Leviticus 4:1', 'Leviticus', 4, 1, '&nbsp;مالِک خُدائ موسىٰ ته حُکم وکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2718, 'Leviticus 4:2', 'Leviticus', 4, 2, '&nbsp;چې بنى اِسرائيلو ته ووايه چې کۀ څوک ګناه وکړى او په غلطۍ سره د مالِک خُدائ حُکمونه مات کړى، نو هغه به دا قانون منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2719, 'Leviticus 4:3', 'Leviticus', 4, 3, '&nbsp;کۀ چرې مشر اِمام ګناه وکړى او د هغې په ذريعه خلق ګناهګار شى، نو هغه به يو سخے پېش کوى چې هيڅ عېب په کښې نۀ وى او د خپلې ګناه دپاره به يې مالِک خُدائ ته قربانى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2720, 'Leviticus 4:4', 'Leviticus', 4, 4, '&nbsp;هغه به سخے د مقدسې خېمې دروازې خولې ته راولى، او په سر به ورته خپل لاس کېږدى، او د مالِک خُدائ په حضور کښې به يې هلته حلال کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2721, 'Leviticus 4:5', 'Leviticus', 4, 5, '&nbsp;بيا به مشر اِمام د سخى لږه وينه واخلى او خېمې ته به يې دننه يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2722, 'Leviticus 4:6', 'Leviticus', 4, 6, '&nbsp;هغه به خپله ګوته په وينه کښې ډُوبه کړى او دا دې اووۀ ځله د مقدسې پړدې مخې ته وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2723, 'Leviticus 4:7', 'Leviticus', 4, 7, '&nbsp;بيا به هغه لږه وينه په خېمه کښې د خوشبويۍ د قربان‌ګاه په ښکرو باندې ولګوى. هغه به پاتې شوې وينه د سوزېدونکې نذرانو قربان‌ګاه په بېخ کښې توئ کړى، کومه چې د خېمې د دروازې په خولۀ کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2724, 'Leviticus 4:8', 'Leviticus', 4, 8, '&nbsp;هغه به د دې سخى نه ټوله وازګه واخلى، هغه وازګه کومه چې په کولمو باندې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2725, 'Leviticus 4:9', 'Leviticus', 4, 9, '&nbsp;پښتورګى او کومه وازګه چې ورباندې پرته وى او د اينې ښۀ حِصه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2726, 'Leviticus 4:10', 'Leviticus', 4, 10, '&nbsp;اِمام به دا وازګه واخلى او د سوزېدونکې نذرانو په قربان‌ګاه باندې به يې وسوزوى، هم هغه شان لکه چې کوم عمل د سلامتۍ د نذرانې دپاره حلال شوى ځناور وازګې سره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2727, 'Leviticus 4:11', 'Leviticus', 4, 11, '&nbsp;خو هغه به د دې څرمن، ټوله غوښه، سر، پښې، دنننى اندامونه سره د کولمو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2728, 'Leviticus 4:12', 'Leviticus', 4, 12, '&nbsp;دا هر څۀ به د خېمو نه بهر هغه پاک ځائ ته يوسى چرته چې ايره غورزولے کيږى، نو هلته دې يې هغه د لرګو په اور باندې وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2729, 'Leviticus 4:13', 'Leviticus', 4, 13, '&nbsp;کۀ چرې د اِسرائيلو ټول قوم ګناه وکړى او په غلطۍ سره د مالِک خُدائ د حُکمونو نه د يو حُکم ماتولو په وجه ګناهګار شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2730, 'Leviticus 4:14', 'Leviticus', 4, 14, '&nbsp;بيا چې څنګه د ګناه پته ورته ولګى، نو قوم به د ګناه د نذرانې په توګه يو سخے راولى. هغوئ به دا د مالِک خُدائ د حضور مقدسې خېمې ته راولى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2731, 'Leviticus 4:15', 'Leviticus', 4, 15, '&nbsp;د قوم مشران به د دې په سر خپل لاسونه کېږدى او سخے دې هلته حلال کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2732, 'Leviticus 4:16', 'Leviticus', 4, 16, '&nbsp;مشر اِمام به د سخى لږه وينه واخلى او خېمې ته به يې دننه يوسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2733, 'Leviticus 4:17', 'Leviticus', 4, 17, '&nbsp;خپله ګوته دې په وينه کښې ډُوبه کړى او هغه دې اووۀ ځله د مالِک خُدائ په حضور کښې د پړدې په مخکښې وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2734, 'Leviticus 4:18', 'Leviticus', 4, 18, '&nbsp;هغه به لږه وينه د خوشبويۍ د قربان‌ګاه په ښکرونو پورې ولګوى چې دا د مالِک خُدائ په حضور کښې دننه په خېمه کښې ده او پاتې شوې وينه دې د سوزېدونکې نذرانې د قربان‌ګاه په بېخ کښې توئ کړى، کومه چې د خېمې د دروازې په خولۀ کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2735, 'Leviticus 4:19', 'Leviticus', 4, 19, '&nbsp;بيا به هغه د سخى ټوله وازګه واخلى او په قربان‌ګاه به يې وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2736, 'Leviticus 4:20', 'Leviticus', 4, 20, '&nbsp;هغه به د دې سخى سره هم هغه شان وکړى لکه څنګه چې هغۀ د ګناه د نذرانې د سخى سره کړى وُو، نو داسې به اِمام د خلقو د ګناه دپاره کفاره ادا کړى او هغوئ به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2737, 'Leviticus 4:21', 'Leviticus', 4, 21, '&nbsp;بيا به هغه سخے د خېمو نه بهر يوسى او وبه يې سوزوى، لکه څنګه چې هغه د خپلې ګناه دپاره پېش کړے شوے سخے سوزوى. دا نذرانه د قوم د ګناه د کفارې دپاره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2738, 'Leviticus 4:22', 'Leviticus', 4, 22, '&nbsp;کۀ يو مشر ګناه وکړى او په غلطۍ سره د مالِک خُدائ د حُکمونو نه د يو حُکم ماتولو په وجه ګناهګار شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2739, 'Leviticus 4:23', 'Leviticus', 4, 23, '&nbsp;او چې د خپلې ګناه پته ورته ولګى، نو هغه به د خپلې نذرانې په توګه يو چېلے راولى چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2740, 'Leviticus 4:24', 'Leviticus', 4, 24, '&nbsp;هغه به خپل لاس د چېلى په سر کېږدى او د قربان‌ګاه هغه طرف ته به يې حلال کړى، چرته چې د سوزېدونکې نذرانې ځناور حلالولے شى. دا د ګناه د لرې کولو نذرانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2741, 'Leviticus 4:25', 'Leviticus', 4, 25, '&nbsp;اِمام به خپله ګوته د ځناور په وينه کښې ډُوبه کړى، دا دې د قربان‌ګاه په ښکرونو پورې ولګوى او پاتې شوې وينه دې د قربان‌ګاه په بېخ کښې توئ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2742, 'Leviticus 4:26', 'Leviticus', 4, 26, '&nbsp;بيا به هغه د دې ټوله وازګه په قربان‌ګاه باندې وسوزوى، لکه څنګه چې هغه د سلامتۍ د نذرانې دپاره حلال شوى ځناور وازګه سوزوى. داسې به اِمام د هغه مشر دپاره د ګناه کفاره ادا کړى او هغه به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2743, 'Leviticus 4:27', 'Leviticus', 4, 27, '&nbsp;کۀ يو عام کس ګناه وکړى او په غلطۍ سره د مالِک خُدائ د حُکمونو نه د يو حُکم ماتولو په وجه ګناهګار شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2744, 'Leviticus 4:28', 'Leviticus', 4, 28, '&nbsp;نو چې څنګه د ګناه پته ورته ولګى، نو هغه به د خپلې نذرانې په توګه يوه چېلۍ راولى چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2745, 'Leviticus 4:29', 'Leviticus', 4, 29, '&nbsp;هغه به خپل لاس د دې په سر کېږدى او د قربان‌ګاه په هغه طرف به يې حلاله کړى، چرته چې د سوزېدونکې نذرانې دپاره ځناور حلاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2746, 'Leviticus 4:30', 'Leviticus', 4, 30, '&nbsp;اِمام به خپله ګوته د دې ځناور په وينه کښې ډُوبه کړى، دا به د قربان‌ګاه په ښکرونو پورې ولګوى او پاتې شوې وينه به د قربان‌ګاه په بېخ کښې توئ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2747, 'Leviticus 4:31', 'Leviticus', 4, 31, '&nbsp;بيا به هغه ټوله وازګه ترې نه لرې کړى، لکه څنګه چې د سلامتۍ د نذرانې دپاره حلال شوى ځناور نه لرې کولے شى او هغه به دا په قربان‌ګاه باندې وسوزوى ځکه چې په مالِک خُدائ دا خوشبو ښۀ لګى. نو داسې به اِمام د هغه کس د ګناه کفاره ادا کړى او هغه به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2748, 'Leviticus 4:32', 'Leviticus', 4, 32, '&nbsp;کۀ يو کس د ګناه د نذرانې دپاره د ګډو نه څۀ راولى، نو هغه دې يوه ګډه وى چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2749, 'Leviticus 4:33', 'Leviticus', 4, 33, '&nbsp;هغه به خپل لاس د دې په سر کېږدى او د قربان‌ګاه په هغه طرف به يې حلاله کړى، چرته چې د سوزېدونکې نذرانې دپاره ځناور حلاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2750, 'Leviticus 4:34', 'Leviticus', 4, 34, '&nbsp;اِمام به خپله ګوته د ځناور په وينه کښې ډُوبه کړى، د قربان‌ګاه په ښکرونو پورې دې دا وينه ولګوى او پاتې شوې وينه به هغه د دې په بېخ کښې توئ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2751, 'Leviticus 4:35', 'Leviticus', 4, 35, '&nbsp;بيا به هغه د دې ټوله وازګه لرې کړى، لکه څنګه چې د سلامتۍ د نذرانې دپاره حلال شوى ځناور نه وازګه لرې کيږى او هغه به په اور سوزېدونکې نذرانو سره په قربان‌ګاه باندې وسوزوى کوم چې مالِک خُدائ ته پېش کيږى. داسې به اِمام د هغه کس د ګناه دپاره کفاره ادا کړى او هغه به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2752, 'Leviticus 5:1', 'Leviticus', 5, 1, '&nbsp;په دې حالاتو کښې د ګناه نذرانې ضرورى ګڼلے کيږى. کۀ څوک د ګواهۍ ورکولو دپاره عدالت ته وغوښتلے شى او هغه معلومات نۀ ورکوى چې څۀ يې ليدلى يا اورېدلى وى، نو هغۀ ته دې د خپلو بدو سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2753, 'Leviticus 5:2', 'Leviticus', 5, 2, '&nbsp;کۀ څوک په غلطۍ سره يو حرام څيز له لاس وروړى، لکه چې يو مړ مردار ځناور له، نو هغه ناپاک او ګناهګار دے چې څنګه ورته پته ولګى چې هغۀ دا خطا کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2754, 'Leviticus 5:3', 'Leviticus', 5, 3, '&nbsp;کۀ څوک په غلطۍ سره د انسان يو ناپاک ځائ يا څيز له لاس وروړى، خو چې څنګه ورته پته ولګى چې هغۀ دا خطا کړې ده نو هغه په دې سره ناپاکه او ګناه ګار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2755, 'Leviticus 5:4', 'Leviticus', 5, 4, '&nbsp;کۀ څوک بغېر د سوچ کولو نه قسم وخورى، چې دا قسم د هر څيز په حقله وى کۀ قسم ښۀ وى او يا بد وى، نو هغه ناپاکه او ګناهګار دے چې څنګه ورته پته ولګى چې هغۀ څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2756, 'Leviticus 5:5', 'Leviticus', 5, 5, '&nbsp;کله چې يو کس ګناه وکړى، نو هغه دې خامخا د ګناه اِقرار وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2757, 'Leviticus 5:6', 'Leviticus', 5, 6, '&nbsp;او د خپلې ګناه په جرمانه کښې به هغه خامخا يوه ګډه يا چېلۍ مالِک خُدائ ته د نذرانې په توګه راولى. اِمام به د هغه کس د ګناه دپاره کفاره ادا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2758, 'Leviticus 5:7', 'Leviticus', 5, 7, '&nbsp;کۀ هغه کس ګډه يا چېلۍ نۀ شى اخستلے، نو هغه به د خپلې ګناه په بدل کښې دوه ګوګوشتکې يا دوه کونترې راوړى، يوه به د ګناه د نذرانې دپاره او بله به د سوزېدونکې نذرانې دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2759, 'Leviticus 5:8', 'Leviticus', 5, 8, '&nbsp;هغه به دا اِمام له راوړى، نو وړومبۍ به مارغۀ د ګناه د نذرانې دپاره پېش کړى. د دې څټ به تاو کړى خو چې سر ترې نه بېل نۀ شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2760, 'Leviticus 5:9', 'Leviticus', 5, 9, '&nbsp;او څۀ وينه دې د قربان‌ګاه په يو طرف باندې وشيندى، پاتې شوې وينه دې د قربان‌ګاه په بېخ کښې وڅڅولے شى. دا د ګناه د لرې کولو دپاره يوه نذرانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2761, 'Leviticus 5:10', 'Leviticus', 5, 10, '&nbsp;بيا د اصُولو په مطابق هغه دوېم مارغۀ دې د سوزېدونکې نذرانې په توګه پېش کړى. داسې به اِمام د هغه کس د ګناه دپاره کفاره ادا کړى کومه چې هغۀ کړې ده او هغه به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2762, 'Leviticus 5:11', 'Leviticus', 5, 11, '&nbsp;کۀ هغه کس دوه ګوګوشتکې يا دوه کونترې هم نۀ شى راوړلے، نو هغه به يو کلو اوړۀ د ګناه د نذرانې په توګه راوړى. هغه دې په دې کښې د زيتُونو تېل يا خوشبوئى نۀ اچوى، ځکه چې دا د ګناه نذرانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2763, 'Leviticus 5:12', 'Leviticus', 5, 12, '&nbsp;هغه کس به دا اِمام له راوړى، اِمام به يو موټے ترې نه د نښې په توګه واخلى چې دا ټول مالِک خُدائ ته پېش کړے شوى دى او په اور سوزېدونکې نذرانې سره به يې په قربان‌ګاه باندې وسوزوى. دا يوه داسې نذرانه ده چې ګناه لرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2764, 'Leviticus 5:13', 'Leviticus', 5, 13, '&nbsp;داسې به اِمام د هغه کس د ګناه دپاره کفاره ادا کړى چې په دې مختلفو ګناهونو کښې يې کومه ګناه هم کړې وى نو هغه به معاف شى. پاتې شوى اوړۀ به هم د غلې نذرانې په شان د اِمام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2765, 'Leviticus 5:14', 'Leviticus', 5, 14, '&nbsp;مالِک خُدائ موسىٰ ته دا اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2766, 'Leviticus 5:15', 'Leviticus', 5, 15, '&nbsp;کۀ يو کس په غلطۍ سره داسې ګناه وکړى او د هغه قيمت په ورکولو کښې ناکام شى چې کوم مالِک خُدائ ته پېش کول وُو، نو هغه به د ګناه د تاوان د نذرانې په توګه يو داسې ګډ يا چېلے مالِک خُدائ ته راولى چې هيڅ عېب په کښې نۀ وى. د دې قيمت به د منلے شوى معيار په مطابق مقررولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2767, 'Leviticus 5:16', 'Leviticus', 5, 16, '&nbsp;هغه به خامخا هغه پېسې ورکوى چې د کومو په ورکولو کښې ناکام شوے وى او شل فيصده دې زياتې هم ورکړى. هغه به دا پېسې اِمام له ورکړى او اِمام به د هغه کس د ګناه د تاوان د نذرانې دپاره ځناور پېش کړى او هغه کس به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2768, 'Leviticus 5:17', 'Leviticus', 5, 17, '&nbsp;کۀ څوک يوه داسې ګناه وکړى چې په غلطۍ سره د مالِک خُدائ د حُکمونو نه يو حُکم مات کړى، نو هغه ګناهګار دے او جرمانه به ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2769, 'Leviticus 5:18', 'Leviticus', 5, 18, '&nbsp;هغه به خامخا اِمام ته د ګناه د تاوان د نذرانې په توګه يو ګډ يا چېلے راولى چې هيڅ عېب په کښې نۀ وى. د دې قيمت به د منلے شوى معيار په مطابق مقررولے شى. اِمام به د هغۀ د ګناه دپاره کفاره ادا کړى کومه چې هغۀ په غلطۍ سره کړې وى او هغه به معاف کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2770, 'Leviticus 5:19', 'Leviticus', 5, 19, '&nbsp;دا د هغې د ګناه د تاوان نذرانه ده کومه چې هغۀ د مالِک خُدائ خِلاف کړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2771, 'Leviticus 6:1', 'Leviticus', 6, 1, '&nbsp;مالِک خُدائ موسىٰ ته دا اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2772, 'Leviticus 6:2', 'Leviticus', 6, 2, '&nbsp;کۀ څوک د مالِک خُدائ خِلاف داسې ګناه وکړى، لکه چې د يو اِسرائيلى امانت واپس ورنۀ کړى، يا د چا نه څۀ څيز پټ کړى، يا څوک دوکه کړى، نو يوه نذرانه به ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2773, 'Leviticus 6:3', 'Leviticus', 6, 3, '&nbsp;يا کۀ يو ورک شوے څيز پېدا کړى او د هغې په حقله دروغ ووائى او داسې قسم وخورى چې هغۀ دا نۀ دے موندلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2774, 'Leviticus 6:6', 'Leviticus', 6, 6, '&nbsp;هغه دې اِمام له يو داسې بې‌عېبه ګډ يا چېلے راولى چې مالِک خُدائ ته يې د ګناه د تاوان د نذرانې په توګه پېش کړى. د دې قيمت به د منلے شوى معيار په مطابق مقررولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2775, 'Leviticus 6:7', 'Leviticus', 6, 7, '&nbsp;اِمام به د هغه کس د ګناه دپاره کفاره ادا کړى او هغه به معاف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2776, 'Leviticus 6:8', 'Leviticus', 6, 8, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2777, 'Leviticus 6:9', 'Leviticus', 6, 9, '&nbsp;چې هارون او د هغۀ زامنو ته د سوزېدونکې نذرانو په حقله دا اصُول وښايه. يوه سوزېدونکې نذرانه به ټوله شپه په قربان‌ګاه باندې پرېښودلے شى او اور دې بل وساتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2778, 'Leviticus 6:10', 'Leviticus', 6, 10, '&nbsp;بيا به اِمام خپله د کتان چُوغه او د کتان جانګے واغوندى، په قربان‌ګاه باندې د سوزېدونکې نذرانې نه پاتې شوې ايرې به لرې کړى او د قربان‌ګاه په څنګ کښې به يې واچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2779, 'Leviticus 6:11', 'Leviticus', 6, 11, '&nbsp;بيا دې جامې بدلې کړى او ايرې دې د خېمو نه بهر يو پاک ځائ ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2780, 'Leviticus 6:12', 'Leviticus', 6, 12, '&nbsp;په قربان‌ګاه دې اور بل وساتلے شى خو چې مړ نۀ شى. اِمام به هر سحر په دې باندې لرګى ږدى، سوزېدونکې نذرانه به په دې سمه ږدى او د سلامتۍ د نذرانې وازګه دې ورباندې سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2781, 'Leviticus 6:13', 'Leviticus', 6, 13, '&nbsp;اور دې خامخا په قربان‌ګاه بل وساتلے شى او چې کله هم مړ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2782, 'Leviticus 6:14', 'Leviticus', 6, 14, '&nbsp;دا د غلې نذرانې دپاره اصُول دى. د هارون د خاندان يو اِمام به د مالِک خُدائ په حضور کښې د قربان‌ګاه په مخکښې د غلې نذرانه پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2783, 'Leviticus 6:15', 'Leviticus', 6, 15, '&nbsp;بيا به هغه د ښو اوړو چې تېل ورسره ګډ وى او خوشبوئى ورباندې پرته وى د هغې نه دې يو موټے واخلى او په قربان‌ګاه باندې به يې د يوې نښې په توګه وسوزوى چې دا ټوله مالِک خُدائ ته پېش کړے شوې ده. د دې نذرانې خوشبو په مالِک خُدائ ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2784, 'Leviticus 6:18', 'Leviticus', 6, 18, '&nbsp;په راتلونکى ټولو وختونو کښې د هارون د اولاد هر يو نارينه مالِک خُدائ ته په اور سوزېدونکې نذرانې نه خپله برخه د همېشه دپاره خوړلے شى. هر څوک يا هر څيز چې د هغې سره ولګى نو هغه به هم مقدس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2785, 'Leviticus 6:19', 'Leviticus', 6, 19, '&nbsp;بيا مالِک خُدائ موسىٰ ته دا اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2786, 'Leviticus 6:20', 'Leviticus', 6, 20, '&nbsp;په کومه ورځ چې د هارون د خاندان يو اِمام مقررولے شى نو هغه به يو کلو ښۀ اوړۀ مالِک خُدائ ته د نذرانې په توګه پېش کوى د عامې غلې د نذرانې په شان، نيم په سحر کښې او نيم په ماښام کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2787, 'Leviticus 6:21', 'Leviticus', 6, 21, '&nbsp;دا به په تېلو کښې ګډ شى، په تبخى به پاخۀ کړے شى او چُورى به کړے شى او د غلې د نذرانې په توګه به پېش کړے شى، د دې خوشبو په مالِک خُدائ ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2788, 'Leviticus 6:22', 'Leviticus', 6, 22, '&nbsp;په راتلونکى ټولو وختونو کښې به د هارون د اولاد هر يو کس دا نذرانه تياروى کوم چې د مشر اِمام په توګه خِدمت کوى. مالِک خُدائ ته د پېش کړے شوې قربانۍ په توګه دا به ټوله وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2789, 'Leviticus 6:23', 'Leviticus', 6, 23, '&nbsp;د اِمام د غلې د نذرانې يوه برخه به هم نۀ شى خوړلے، ټوله به خامخا سوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2790, 'Leviticus 6:24', 'Leviticus', 6, 24, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2791, 'Leviticus 6:25', 'Leviticus', 6, 25, '&nbsp;هارون او د هغۀ زامنو ته د ګناه د نذرانې دپاره دا اصُول وښايه. د ګناه د نذرانې ځناور به د مالِک خُدائ په حضور کښې حلالولے شى، چرته چې د سوزېدونکې نذرانې دپاره ځناور حلاليږى. دا يوه ډېره مقدسه نذرانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2792, 'Leviticus 6:26', 'Leviticus', 6, 26, '&nbsp;کوم اِمام چې دا ځناور قربانى کوى هغه به دا په مقدس ځائ کښې وخورى چې هغه د مالِک خُدائ د حضور د خېمې دربار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2793, 'Leviticus 6:27', 'Leviticus', 6, 27, '&nbsp;هر څوک يا هر څيز چې د هغې سره ولګى نو هغه به هم مقدس شى. کۀ جامې د ځناور په وينه ولړلے شى، نو هغه به خامخا په مقدس ځائ کښې وينځلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2794, 'Leviticus 6:28', 'Leviticus', 6, 28, '&nbsp;د خاورې په کوم لوښى کښې چې غوښه يشولے شوې وى هغه دې مات کړے شى او کۀ د زېړو لوښے استعمال شوے وى، نو هغه دې ومږلے شى او په اوبو کښې دې کنګال کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2795, 'Leviticus 6:29', 'Leviticus', 6, 29, '&nbsp;د اِمامانو د کورَنو هر نر دا نذرانه خوړلے شى، دا ډېره مقدسه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2796, 'Leviticus 6:30', 'Leviticus', 6, 30, '&nbsp;خو کۀ د کوم ځناور وينه مقدسې خېمې ته دننه راوړلے شى او د ګناه د کفارې ادا کولو دپاره استعمال شى، نو هغه ځناور دې نۀ شى خوړلے چې د کوم نه وينه اخستے شوې وى، او دا دې وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2797, 'Leviticus 7:1', 'Leviticus', 7, 1, '&nbsp;د ګناه د نذرانو د ورکولو دپاره دا اصُول دى، کومې چې ډېرې مقدسې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2798, 'Leviticus 7:2', 'Leviticus', 7, 2, '&nbsp;د ګناه د تاوان د نذرانې دپاره ځناور به هلته حلاليږى، چرته چې د سوزېدونکې نذرانې ځناور حلاليږى او د دې وينه دې د قربان‌ګاه په ټولو طرفونو وشيندلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2799, 'Leviticus 7:3', 'Leviticus', 7, 3, '&nbsp;د دې ټوله وازګه دې په قربان‌ګاه باندې پېش کړے شى، لم، هغه وازګه چې په کولمو پرته وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2800, 'Leviticus 7:4', 'Leviticus', 7, 4, '&nbsp;پښتورګى او هغه وازګه چې ورباندې پرته وى او د اينې ښۀ حِصه هم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');